import {ToolRegistry} from './registry.js';

it('reuses the registered weather schema across ten calls @specs/hal-engine-tool-input-validation/spec.md#6', async () => {
  const registry = new ToolRegistry();
  let schemaReads = 0;
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      get inputSchema() {
        schemaReads++;
        return {type: 'object' as const, properties: {location: {type: 'string'}}, required: ['location']};
      },
    },
    async input => JSON.stringify(input)
  );
  const registrationReads = schemaReads;
  const results = [];
  for (let call = 0; call < 10; call++) {
    results.push(await registry.execute('weather', {location: 'Berlin'}));
  }
  expect({registrationReads, schemaReads, results}).toEqual({
    registrationReads: 1,
    schemaReads: 1,
    results: Array.from({length: 10}, () => ({result: '{\"location\":\"Berlin\"}'})),
  });
});
EOF
